    Had a weird idea/random idea after my last shader.
    I so don't get the math to match buffer/texture 
    across a domain but I magic numbered it to work. 

    code is way messy and some fudging of numbers
    may have occured...

    Box Reveal - Texture Experiment
    01/14/2025  @byt3_m3chanic 

*/

#define R iResolution
#define M iMouse
#define T iTime

#define PI  3.1415926
#define PI2 6.2831853

#define MIN_DIST 1e-3
#define MAX_DIST 40.

#define eoc(t) (t=t-1.)*t*t+1.
#define eic(t) t*t*t


vec3 hit,hp;
mat2 mx,my,nx,ny,mz,mw,nz,nw;

mat2 rot (float a) { return mat2(cos(a),sin(a),-sin(a),cos(a)); }
float hash21( vec2 p ) { return fract(sin(dot(p,vec2(23.43,35.23))) *472.323); }

// timing functions
float lerp (float b, float e, float t) { return clamp((t - b) / (e - b), 0., 1.); }

float box(vec3 p, vec3 b){
    vec3 d = abs(p)-b; return length(max(d,0.))+min(max(d.x,max(d.y,d.z)),.0);
}

//globals
vec3 s_hit, g_hit;
vec2 s_id, g_id;
float tspeed=0., tmod=0., xmod=0., mtt, xsc;

//scales for all things
const float scale = .5;
const float scale_h = scale/2.;
const vec2 s = vec2(scale*2.25);

const vec2 pos = vec2(.5,-.5);
const vec2[4] ps4 = vec2[4](pos.yx,pos.xx,pos.xy,pos.yy);

float pattern(inout vec3 q, vec2 id) {
    float res = 1e5;
    float rnd = hash21(id);

    float ths = (length(id)*.5)+fract(rnd*4374.35);
    float bhs = (rnd*1.37)+fract(rnd*4324.35);

    ths = floor(mtt)<6. ? ths:bhs;
    // turn based on mod time
    //ths += rnd;
    float t9 = lerp(ths+.5 ,ths+ 1.5,xmod);
    float t1 = lerp(ths+1. ,ths+ 1.5,tmod);
    float t2 = lerp(ths+7. ,ths+ 7.5,tmod);
    float t3 = lerp(ths+13.,ths+13.5,tmod);
    float t4 = lerp(ths+19.,ths+19.5,tmod);  
    t1 = eoc(t1); t1 = eic(t1);
    t2 = eoc(t2); t2 = eic(t2);
    t3 = eoc(t3); t3 = eic(t3);
    t4 = eoc(t4); t4 = eic(t4);

    float ff = .24*sin((id.x+id.y)*.5+T*1.5);
    ff = eoc(ff); ff = eic(ff);
    ff = mix(ff,.0,.51+.49*cos(T*.23));

    vec3 nq = q-vec3(0,ff+((t2-t3)+(t1-t4))*scale,0);

    // messy first draft
    float rf = 1.5707;

    nx = rot(rf*(t1-t2));
    ny = rot(rf*(t3-t4));
    nq.zy *= nx;
    nq.xz *= ny;

    nz = rot(rf*(t1-t4));
    nw = rot(rf*(t2-t3));
    nq.zy *= nz;
    nq.xz *= nw;

    xsc = .75+.25*cos(t9*PI2);

    float d = box(nq,vec3(scale_h*xsc))-.015;
    if(d<res) {
        res = d;
        q = nq;
    }
    return res;
}
// block map -v4 tap technique from @Shane
vec2 map(vec3 q3){
    q3.y+=.5;
    vec2 res = vec2(1e5,0.), p, ip, ct = vec2(0);
    float t=1.75, y=1e5, m=1.;
    for(int i =0; i<4; i++){

        ct = ps4[i]/2. -  ps4[0]/2.;
        p = q3.xz - ct*s;
        ip = floor(p/s) + .5;
        p -= (ip)*s;
        vec2 idi = (ip + ct)*s;
        if((idi.x>-4.&&idi.x<4.) && (idi.y>-3.&&idi.y<3.)){

            vec3 q = vec3(p.x,q3.y,p.y);
            float b = pattern(q,idi);

            if(b<t) { 
                t = b;
                s_id = idi, s_hit = q;
                mx=nx, my=ny, mz=nz, mw=nw;
            }
        }
    }

	if(t<res.x) res = vec2(t,1.);
    return res;
}

vec3 normal(vec3 p, float t) {
    float e = MIN_DIST*t;
    vec2 h =vec2(1,-1)*.5773;
    vec3 n = h.xyy * map(p+h.xyy*e).x+
             h.yyx * map(p+h.yyx*e).x+
             h.yxy * map(p+h.yxy*e).x+
             h.xxx * map(p+h.xxx*e).x;
    return normalize(n);
}

vec3 hsv(vec3 c) {
    vec3 rgb = clamp(abs(mod((c.x+T*.03)*6.+vec3(0,4,2),6.)-3.)-1.,0.,1.);
    return c.z * mix(vec3(1),rgb,c.y);
}

float tiles(vec2 uv,vec2 id, float thickness) {
    vec2 q = uv;
    float rnd = hash21(id.xy);
    if(rnd>.5) q.y = -q.y;
    vec2 q2 = length(q-scale_h)<length(q+scale_h) ? q-scale_h : q+scale_h;
    float d1 = abs(length(q2)-scale_h)-thickness;
    if(fract(rnd*32.27)>.85) d1 = min(length(q.x)-thickness,length(q.y)-thickness);
    return d1;
}
// https://learnopengl.com/Advanced-Lighting/Gamma-Correction
vec3 decodeSRGB(vec3 screenRGB) { return pow(screenRGB, vec3(2.2)); }
vec3 render(inout vec3 ro, inout vec3 rd, inout float d) {

    vec3 C = vec3(0), p = ro;
    float m = 0.;

    for(int i=0;i<100;i++) {
        p = ro + rd * d;
        vec2 ray = map(p);
        if(ray.x<MIN_DIST*d||d>MAX_DIST)break;
        d += i<25? ray.x*.25: ray.x;
        m  = ray.y;
    } 
    hp = s_hit;
    g_id = s_id;
    float alpha = 0.;
    if(d<MAX_DIST)
    {
        vec3 n = normal(p,d);
        vec3 lpos =  vec3(-5.,12,-5);
        vec3 l = normalize(lpos-p);
        float diff = clamp(dot(n,l),.001,1.);

        int face;
        vec3 cuv = s_hit, h=vec3(0);

        // quick find the correct face with normal
        vec3 tn = n;
        tn.zy *= mx;
        tn.xz *= my; 
        tn.zy *= mz;
        tn.xz *= mw; 
        vec3 aN = abs(tn);
        ivec3 idF = ivec3(tn.x<-.25? 0 : 5, tn.y<-.25? 1 : 4, tn.z<-.25? 2 : 3);
        face = aN.x>.5? idF.x : aN.y>.5? idF.y : idF.z;

        if(face==0||face==5) { 
            cuv = s_hit.yzx;
            g_id+=vec2(4,3);
            vec2 nuv=vec2(-cuv.y,-cuv.x)-vec2(.25,.25);
            g_id=-g_id;
            h=decodeSRGB(texture(iChannel1,(nuv*.11)-(g_id*1.88) ).rgb);
        }
        if(face==1) { 
            cuv = s_hit.zxy;   
            vec2 uv = cuv.xy;
            float px = fwidth(uv.x);
            g_id+=vec2(4,3);
            vec2 nuv=vec2(cuv.y,-cuv.x)+vec2(2.,2.);
            h=texture(iChannel0,(nuv*vec2(.063,.175))-(g_id*vec2(1.69,1.62)) ).rgb; 
        }
        if(face==4) { 
            cuv = s_hit.zxy;
            g_id+=vec2(4,3);
            vec2 nuv=vec2(cuv.y,cuv.x)-vec2(.25,.25);
            g_id=-g_id;
            h=decodeSRGB(texture(iChannel3,(nuv*.11)-(g_id*1.88)).rgb);
        }
        if(face==2||face==3) { 
            cuv = s_hit.xyz;
            g_id+=vec2(4,3);
            vec2 nuv=vec2(-cuv.y,cuv.x)+vec2(.35,-.85);
            g_id.y=-g_id.y;
            h=texture(iChannel2,(nuv*.11)-(g_id*1.88) ).rgb;
        }

        C = h * diff;

        ro = p+n*.001;
        rd = reflect(rd,n);

    } else {
        C = vec3(.025);
    }
    return vec3(C);
}

float zoom = 7.;
void mainImage( out vec4 O, in vec2 F )
{ 
    tspeed = T*.75;
    tmod = mod(tspeed,24.);
    mtt = mod(tspeed,12.);
    xmod = mod(tspeed,6.);

    vec2 uv = (2.*F.xy-R.xy)/max(R.x,R.y);
    vec3 ro = vec3(uv*zoom,-(zoom));
    vec3 rd = vec3(0,0,1);

    float t1 = lerp(2.,5.,tmod);  
    float t2 = lerp(12.,15.,tmod); 
    t1 = eoc(t1); t1 = eic(t1);
    t2 = eoc(t2); t2 = eic(t2);
    mat2 rx =rot(.88);
    mat2 ry =rot(.28*sin((t1-t2)*2.-1.));

    ro.zy*=rx;rd.zy*=rx;
    ro.xz*=ry;rd.xz*=ry;

    float d = 0.;
    vec3 C =  render(ro, rd, d);
    O = vec4(pow(C, vec3(.4545)),1);
}

/** 
