    tiny shader 005 | 06/26/22 | byt3_m3chanic

    Just playing around - trying to make something smol. 
    some golfing tricks from @dean_the_coder @Fabrice @iapafoto @Shane
*/

#define M           iMouse
#define R           iResolution
#define T           iTime
#define PI2         6.28318530718

#define S           smoothstep
#define L           length
#define Nz          normalize
#define V           vec2(1,0)


#define H21(a) fract(sin(dot(a,vec2(21.23,41.32)))*43758.5453)
#define N(p,e) vec3(map(p-e.xyy),map(p-e.yxy),map(p-e.yyx))
//#define H(hs) .5+.4*cos(PI2*hs+2.*vec3(.95,.97,.90)*vec3(.15,.75,.95))
#define B(a,b,c,d,uv) mix(a,b,u.x)+(c-a)*u.y*(1.-u.x)+(d-b)*u.x*u.y

//iq color functions
vec3 H(float t){ 
    return .35+.4*cos(PI2*t*(vec3(.91,.53,.08)+vec3(.94,.92,.8)) ); 
}

mat2 Q(float a) { return mat2(cos(a),sin(a),-sin(a),cos(a)); }
float ns(vec2 uv) {
    vec2 i=floor(uv),u=fract(uv);
    u=u*u*(3.-2.*u);
    return B(H21(i),H21(i+V.xy),H21(i+V.yx),H21(i+V.xx),uv);
}

float FB(vec2 p) {	
	float h=.5,w=2.5,m=.25,i;
	for (i=0.;i<4.;i++) {h+=w*ns((p*m));w*=.5;m*=2.;}
	return h;
}

float map(vec3 p) { return L(p.y-1.2-.5*sin(p.z*1.5+p.x*.5))-FB(p.xz*1.5)*.65;}

void mainImage(out vec4 O, vec2 F) {
    vec2 uv = (2.*F.xy-R.xy)/max(R.x,R.y);
    vec3 C = vec3(.1),
         p = V.yyy,
         c = V.yyy,
        ro = vec3(0,1,8),
        rd = Nz(vec3(uv,-1));

    mat2 rx = Q(-2.8),
         ry = Q((M.x/R.x)*PI2+T*.05);

    ro.yz*=rx; ro.xz*=ry; 
    rd.yz*=rx; rd.xz*=ry;

    float d=0.;
    for(int i=0; i++<80 && d<75.; ){
        p = ro+rd * d;
        p.x-=1.5*T;
        float x = map(p);
        d+=i<20?.5*x:.75*x;
    }

    float t = map(p);
    vec2 e = vec2(d*.001,0);
    vec3 l = Nz(vec3(2,-15,-5)),
         n = t - N(p,e);
         n = Nz(n);
    vec3 h = H((p.x*.01)+floor(p.y*5.)*.05);

    C = clamp(dot(n,l),.02,.9)*h;
    C = mix(C,H(.39),1.-exp(-.00025*d*d*d));
    O = vec4(C,1);
}

/** 

    License: Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License

    Year of Truchets #xxx
    xx/xx/2023  @byt3_m3chanic
    Truchet Core \M/->.<-\M/ 2023 

*/


#define R iResolution
#define T iTime
#define M iMouse

#define P9          1.57078
#define PI          3.14159265359
#define PI2         6.28318530718

#define MIN_DIST    .0001
#define MAX_DIST    50.

vec3 hp,hitpoint;
float gid,sid;
float hspeed=0.,tspeed=0.,fspeed=0.,tmod=0.,ga1=0.,ga2=0.,ga3=0.,ga4=0.;
mat2 ra1,ra2,ra3,ra4;

// change size
const float csize = 3.;
const float dsize = 12.;//csize*4.;
const float xsize = 24.;//dsize*2.;
const float psize = 1.5;//csize/2.;

mat2 rot(float a){ return mat2(cos(a),sin(a),-sin(a),cos(a)); }
const vec2[4] ps4 = vec2[4](vec2(csize,-csize),vec2(csize,csize),vec2(-csize,csize),vec2(-csize,-csize));
void rov(inout vec2 q, int ct, mat2 ga){q-=ps4[ct];q*=ga;q+=ps4[ct];}
float hash21(vec2 p) {return fract(sin(dot(p,vec2(4323.232,323.123))))*3434.32323;}
float lsp(float b, float e, float t){return clamp((t-b)/(e-b),0.,1.); }
float ezin(float n) {n = n*n*n; return n;}
float box(vec3 p, vec3 b) { vec3 q=abs(p)-b; return length(max(q,0.)) + min(max(q.x,max(q.y,q.z)),0.);}

vec2 map(vec3 p) {
    vec2 res = vec2(1e5,0.);

    p.x+=fspeed;
    vec3 q = p-vec3(csize-1.);

    if(ga1>0.) rov(q.xy,0,ra1);
    if(ga2>0.) rov(q.xy,1,ra2);
    if(ga3>0.) rov(q.xy,2,ra3);
    if(ga4>0.) rov(q.xy,3,ra4);

    float d1 = box(q,vec3(csize)-.025)-.025;

    float da = box(q,vec3(4,1,1)-.025)-.025;
    float db = box(q,vec3(1,4,1)-.025)-.025;
    float dc = box(q,vec3(1,1,4)-.025)-.025;
    float b2 = min(min(da,db),dc);
    d1=max(d1,-b2);

    if(d1<res.x) {
        res=vec2(d1,1.);
        hp=q;
        gid=1.;
    }

    float d2 = p.y+1.;
    if(d2<res.x) {
        res=vec2(d2,2.);
        hp=p;
        gid=0.;
    }
    return res;
}

vec3 normal(vec3 p, float t) {
    t*=MIN_DIST;
    float d = map(p).x;
    vec2 e = vec2(t,0);
    vec3 n = d - vec3(
        map(p-e.xyy).x,
        map(p-e.yxy).x,
        map(p-e.yyx).x
    );
    return normalize(n);
}

vec2 marcher(vec3 ro, vec3 rd, inout vec3 p) {
    float d=0.,m=0.;
    for(int i=0;i<80;i++){
        vec2 t = map(p);
        d += i<24? t.x*.5:t.x;
        m  = t.y;  
        p = ro + rd * d;
        if(abs(t.x)<d*MIN_DIST||d>55.) break;
    } 
    return vec2(d,m);
}

vec3 getFace(vec2 uv) {
    vec3 h = vec3(.0);
    vec2 id = floor(uv);
    vec2 gv = fract(uv)-.5;

    float ck = mod(id.x+id.y,2.)*2.-1.;
    float px = 12./R.x;
    float rnd = fract(hash21(id+sid)*32.121);
    if(rnd<.45) gv.x=-gv.x;//gv *=rot(1.5707);

    vec2 d2 = vec2(length(gv-.5), length(gv+.5));
    vec2 gx = d2.x<d2.y? vec2(gv-.5) : vec2(gv+.5);
    float cx = length(gx)-.5;
    if(rnd>.65) cx = min(length(gv.x)-.005,length(gv.y)-.005);

    float d5 = abs(max(abs(gv.x),abs(gv.y))-.5)-.005;
    cx=abs(abs(abs(cx)-.15)-.075)-.025;

    //cx=abs(cx)-.005;
    h = mix(h, vec3(.9),smoothstep(-px,px,cx));
    h = mix(h, vec3(.1),smoothstep(px,-px,d5));
    return h;
}

void mainImage( out vec4 O, in vec2 F ) {
    float hspeed;

    tspeed = (T+34.)*.9;
    tmod = mod(tspeed,10.);
    if(tmod==10.) { fspeed -=dsize;hspeed -=dsize;}
    fspeed = fract(tspeed*.1)*xsize;
    hspeed = (tspeed*.1)*xsize;

    // timing
    ga1 = ezin(lsp(0.,1.5,tmod));
    ga2 = ezin(lsp(1.5,3.,tmod));
    ga3 = ezin(lsp(3.,4.5,tmod));
    ga4 = ezin(lsp(4.5,6.,tmod));

    // rotation precal
    if(ga1>0.) ra1 = rot(-ga1*P9);
    if(ga2>0.) ra2 = rot(-ga2*P9);
    if(ga3>0.) ra3 = rot(-ga3*P9);
    if(ga4>0.) ra4 = rot(-ga4*P9);

    // uv ro + rd
    vec2 uv = (2.* F.xy-R.xy)/max(R.x,R.y);
    vec3 ro = vec3(csize-1.,csize,6);
    vec3 rd = normalize(vec3(uv,-1));

    // mouse //
    float x = M.xy==vec2(0) || M.z<1. ? 0. : (M.y/R.y*.15-.0725)*PI;
    float y = M.xy==vec2(0) || M.z<1. ? 0. : (M.x/R.x*1.-.5)*PI;

    float ff = (.13*sin(T*.2));
    mat2 rx = rot(-.1-x), ry = rot(-(1.57+y)-ff);

    ro.zy*=rx; ro.xz*=ry;
    rd.zy*=rx; rd.xz*=ry;

    vec3 C=vec3(0), p = ro;

    vec2 ray = marcher(ro,rd,p);
    float d = ray.x, m = ray.y;

    hitpoint = hp; sid = gid;

    if(d<MAX_DIST) {

        vec3 n = normal(p,d);
        vec3 lpos = vec3(-22,22,22);
        vec3 l = normalize(lpos-p);
        float diff = clamp(dot(n,l),0.,1.);

        float shdw = 1.;
        for( float t=.01; t < 12.; ) {
            float h = map(p + l*t).x;
            if( h<MIN_DIST ) { shdw = 0.; break; }
            shdw = min(shdw, 12.*h/t);
            t += h;
            if( shdw<MIN_DIST ) break;
        }
        diff = mix(diff,diff*shdw,.65);

        float spec = .75 * pow(max(dot(normalize(p-ro),reflect(normalize(lpos),n)),0.),24.);
        vec3 h = vec3(1.);

        vec2 cv;
        vec3 tn = n;
        int face = 0;
        if(m==1.) {

            if(ga1>0.) tn.xy*=ra1;
            if(ga2>0.) tn.xy*=ra2;
            if(ga3>0.) tn.xy*=ra3;
            if(ga4>0.) tn.xy*=ra4;

            //@Shane https://www.shadertoy.com/view/3sVBDd
            //finding the face of a cube using normal
            vec3 aN = abs(tn);
            ivec3 idF = ivec3(tn.x<-.25? 0 : 5, tn.y<-.25? 1 : 4, tn.z<-.25? 2 : 3);
            face = aN.x>.5? idF.x : aN.y>.5? idF.y : idF.z;

            if(face==0) cv = hitpoint.zy+4.;
            if(face==1) cv = hitpoint.zx-4.;
            if(face==2) cv = hitpoint.xy;//
            if(face==3) cv = hitpoint.xy;//
            if(face==4) cv = hitpoint.zx+8.;
            if(face==5) cv = hitpoint.zy-8.;

            cv*=.5;
            cv-=psize;
            h = vec3(.0);
            h = getFace(cv)*vec3(.19,.42,.47);

        };
        if(m==2.) {
            vec2 cv = p.xz;
            h = vec3(.0);
            vec2 uz = cv-vec2(-hspeed,0.)-1.;
            h = getFace(uz*.5)*vec3(.19,.42,.47);
        };

        C = h * diff;

    }

    C = mix(C,vec3(.19,.42,.47), 1.-exp(-.00005*d*d*d));
    //C = pow(C, vec3(.4545));
    O = vec4(C,1.);
}
